public with sharing class UpdateContactAddresses
        implements Database.Batchable<sObject>, Database.Stateful {
    public Integer recordsProcessed = 0;
    public Database.QueryLocator start(Database.BatchableContext bc) {
        return Database.getQueryLocator(
            'SELECT Id, BillingCity, (SELECT Id FROM Contacts) FROM Account WHERE BillingCountry = \'USA\'');
    }
    public void execute(Database.BatchableContext bc, List<Account> scope) {
        List<Contact> cts = new List<Contact>();
        for (Account a : scope) for (Contact c : a.Contacts) {
            c.MailingCity = a.BillingCity; cts.add(c); recordsProcessed++;
        }
        update cts;
    }
    public void finish(Database.BatchableContext bc) {
        AsyncApexJob job = [SELECT Status, NumberOfErrors, JobItemsProcessed, TotalJobItems
                            FROM AsyncApexJob WHERE Id = :bc.getJobId()];
    }
}

public with sharing class UpdateParentAccount implements Queueable {
    private List<Account> accounts; private Id parent;
    public UpdateParentAccount(List<Account> records, Id id) { accounts = records; parent = id; }
    public void execute(QueueableContext context) {
        for (Account a : accounts) a.ParentId = parent;
        update accounts;
    }
}
