public with sharing class RemindOpptyOwners implements Schedulable {
    public void execute(SchedulableContext ctx) {
        List<Task> tasks = new List<Task>();
        for (Opportunity o : [SELECT Id, OwnerId FROM Opportunity
                              WHERE IsClosed = false AND CloseDate < TODAY]) {
            tasks.add(new Task(Subject = 'Update the Opportunity!', WhatId = o.Id, OwnerId = o.OwnerId));
        }
        insert tasks;
    }
}
